function makeDispenser(prefix) {
  let next = 1;                       // lives on after makeDispenser returns
  return function () {
    return prefix + next++;
  };
}

const canteen = makeDispenser("C");
const library = makeDispenser("L");
console.log(canteen(), canteen(), library(), canteen(), library());
console.log(typeof next);             // not visible out here: the closure keeps it private

const withVar = [];
for (var i = 1; i <= 3; i++) withVar.push(() => i);    // one i shared by every function
const withLet = [];
for (let j = 1; j <= 3; j++) withLet.push(() => j);    // a new j for each iteration
console.log("var:", withVar.map((f) => f()).join(" "));
console.log("let:", withLet.map((f) => f()).join(" "));

