const lines = require("fs").readFileSync(0, "utf8").split("\n").map((s) => s.trim());

let next = 1; // TODO: every counter must have its OWN numbering; this one is shared

function makeDispenser(prefix) {
  return () => prefix + next++;
}

const dispensers = {};
const out = [];
const t = Number(lines[0]);
for (let k = 1; k <= t; k++) {
  const counter = lines[k];
  if (!(counter in dispensers)) dispensers[counter] = makeDispenser(counter);
  out.push(dispensers[counter]());
}
console.log(out.join("\n"));

